#!/usr/bin/env node
/**
 * scripts/scribe-bundle.mjs — THE SCRIBE'S DENO BUNDLE (W1 deliverable 3;
 * DESIGN_SCRIBE_GENERATION_TIME_PROSE §6).
 *
 * The tier-0 refuter has to run where the render runs, which is a Supabase Edge Function on Deno
 * with no node_modules and no build step at deploy time. So `refuteUnit.js` and `epochRecord.js`
 * plus every module they transitively reach are bundled into ONE dependency-free ESM file that
 * ships in tree under `supabase/functions/_shared/`, exactly as the five existing shared bundles do.
 *
 * ── ⛔ WHY THIS IS A SECOND SCRIPT AND NOT A SIXTH ROW OF `build-edge-shared.mjs` ───
 * That file is the estate's bundle builder and its `ENTRIES` table is one line per bundle, so a
 * sixth row is the obvious move. It is not taken here for two reasons and both are recorded so the
 * chair can overrule: (a) `scripts/.size-baseline.json` is an EXACT line ratchet in BOTH directions
 * and a new row grows a baselined file, which the W1 brief bars outright ("new files only"); and
 * (b) this bundle has TWO entry points and that table has one `entry` per row. THE IDIOM IS
 * FOLLOWED EXACTLY ALL THE SAME — the same banner, the same `{entry, sourceHash, inputs}` meta,
 * the same JSDoc-import strip, the same source-hash-of-inputs freshness contract — so the estate
 * has one bundle SHAPE even while it has two builders. The ONE deliberate departure is that this
 * meta carries NO `generatedAt`: a timestamp makes every rebuild a diff, which is the noise a
 * byte-equality `--check` exists to remove. ⭐ FOR THE CHAIR: the two
 * should merge in W2, when a baselined-file edit is on the table anyway.
 *
 * ── ⛔ NO DEPENDENCY IS ADDED. THE PRODUCT'S `package.json` IS A MINT TRIGGER ───────
 * `esbuild` is NOT a declared dependency of this product; it is present in `node_modules` because
 * vite brings it. This script imports it and adds NOTHING to `package.json`. If it is ever absent,
 * the script says so in one plain sentence and exits non-zero rather than half-writing a bundle.
 *
 * ── THE TWO ENTRY POINTS RIDE A VIRTUAL MODULE, NOT A THIRD PRODUCT FILE ───────────
 * A barrel under `src/domain/prose/` would be a third new `src/domain` file, a third census stamp
 * move, and a module that exists only to be bundled. esbuild's `stdin` with a `resolveDir` does
 * the same job with no product byte: the virtual module re-exports both leaves and is the entry.
 *
 *   node scripts/scribe-bundle.mjs            build
 *   node scripts/scribe-bundle.mjs --check    rebuild into memory and diff byte-for-byte
 */
import { fileURLToPath } from 'node:url';
import { dirname, join, relative } from 'node:path';
import {
  writeFileSync, readFileSync, existsSync, mkdirSync,
} from 'node:fs';
import { createHash } from 'node:crypto';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const OUT_DIR = join(ROOT, 'supabase', 'functions', '_shared');
const OUT = 'proseKernel.bundle.js';
const META = 'proseKernel.bundle.meta.json';

/**
 * The leaves the Scribe needs on the server, in the order the virtual entry re-exports them.
 *
 * ⭐ `scribeBrief.js` JOINED AT W3a (chair ruling 25). The prompt builders and the judge are a
 * pure leaf rather than edge TypeScript precisely so that the pilot harness and the edge function
 * can run the SAME ones: the harness imports the leaf from the dock, the function imports it from
 * this bundle, and `scribeCore.ts` re-exports it so `index.ts`'s import list does not change.
 */
export const SCRIBE_ENTRIES = Object.freeze([
  'src/domain/prose/refuteUnit.js',
  'src/domain/prose/epochRecord.js',
  'src/domain/prose/scribeBrief.js',
]);

/** The virtual entry module. It exists only inside esbuild and is never written to disk. */
const VIRTUAL = SCRIBE_ENTRIES.map((e) => `export * from '${join(ROOT, e)}';`).join('\n');

const banner = () => `/**
 * Auto-generated by scripts/scribe-bundle.mjs — DO NOT EDIT BY HAND.
 *
 * Deno-importable bundle of ${SCRIBE_ENTRIES.join(' + ')} plus every transitive dep they reach.
 * This is THE TIER-0 REFUTER as it runs at generation time: pure code, no model, no census on disk.
 * Regenerate after editing any bundled module via:
 *
 *   node scripts/scribe-bundle.mjs
 *
 * Freshness is enforced by tests/lint/scribeBundle.walker.test.js, which rebuilds and compares
 * byte-for-byte and then proves the result loads.
 */
`;

/**
 * Build the bundle into memory.
 * @returns {Promise<{source: string, meta: object}>}
 */
export async function buildScribeBundle() {
  let esbuild;
  try {
    esbuild = await import('esbuild');
  } catch {
    throw new Error(
      'esbuild is not present in node_modules and it may not be added to package.json, which is a mint trigger. '
      + 'Install it in a scratch tree and re-run, or hand-roll the bundle.',
    );
  }
  const result = await esbuild.build({
    stdin: { contents: VIRTUAL, resolveDir: ROOT, sourcefile: 'scribeBundleEntry.js', loader: 'js' },
    write: false,
    bundle: true,
    format: 'esm',
    target: 'es2022',
    platform: 'neutral',
    charset: 'utf8',
    minify: false,
    sourcemap: false,
    logLevel: 'silent',
    external: [],
    banner: { js: banner() },
    metafile: true,
  });
  // ⛔ THE VIRTUAL ENTRY IS DROPPED BY NAME. esbuild keys a `stdin` input on its `sourcefile`,
  // not on `<stdin>`, so a filter on the latter leaves a path that is not on disk in the input
  // list and the hash walk then tries to read it. Measured, the first time this ran.
  const inputPaths = Object.keys(result.metafile.inputs)
    .filter((p) => p !== 'scribeBundleEntry.js' && p !== '<stdin>')
    .map((p) => relative(ROOT, join(ROOT, p)))
    .sort();
  const inputContents = inputPaths
    .map((p) => `${p}:${readFileSync(join(ROOT, p), 'utf8')}`)
    .join('\n');
  const sourceHash = createHash('sha256').update(inputContents).digest('hex').slice(0, 16);

  // ⛔ THE JSDoc-IMPORT STRIP, copied from `build-edge-shared.mjs` with its reason. Bundled app
  // source threads `@param {import('./entryWalker.js').EntryGround}` annotations; esbuild with
  // minify off preserves comments, so those leak into the bundle and break `deno check`, which
  // resolves JSDoc import types against paths that do not exist under `_shared/`. The types are
  // runtime-irrelevant. The banner carries no `import(` so it survives. The recorded hash is over
  // INPUT source, so this output-only strip cannot affect freshness.
  const stripped = result.outputFiles[0].text
    .replace(/\/\*\*[^]*?\*\//g, (block) => (block.includes('import(') ? '' : block));
  const source = stripped.includes('Source hash:')
    ? stripped
    : stripped.replace('DO NOT EDIT BY HAND.', `DO NOT EDIT BY HAND.\n * Source hash: ${sourceHash}`);
  return {
    source,
    meta: {
      entry: SCRIBE_ENTRIES,
      sourceHash,
      inputs: inputPaths,
    },
  };
}

/** @returns {{outFile: string, metaFile: string}} */
export function scribeBundlePaths() {
  return { outFile: join(OUT_DIR, OUT), metaFile: join(OUT_DIR, META) };
}

async function main() {
  const check = process.argv.includes('--check');
  const { outFile, metaFile } = scribeBundlePaths();
  const { source, meta } = await buildScribeBundle();
  const kb = (Buffer.byteLength(source, 'utf8') / 1024).toFixed(1);
  if (check) {
    if (!existsSync(outFile)) {
      console.error(`${OUT} is missing; run \`node scripts/scribe-bundle.mjs\`.`);
      process.exit(1);
    }
    const onDisk = readFileSync(outFile, 'utf8');
    if (onDisk !== source) {
      console.error(`${OUT} is stale; run \`node scripts/scribe-bundle.mjs\`.`);
      process.exit(1);
    }
    const metaOnDisk = JSON.parse(readFileSync(metaFile, 'utf8'));
    if (metaOnDisk.sourceHash !== meta.sourceHash) {
      console.error(`${META} records a different source hash; run \`node scripts/scribe-bundle.mjs\`.`);
      process.exit(1);
    }
    console.log(`[scribe-bundle] verified ${OUT} (inputs ${meta.inputs.length}, ${kb} KB, hash ${meta.sourceHash})`);
    return;
  }
  if (!existsSync(OUT_DIR)) mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync(outFile, source);
  // ⛔ NO `generatedAt`. The five existing metas carry one and it makes every rebuild a diff, which
  // is exactly the noise a byte-equality `--check` exists to remove. This meta is a function of the
  // inputs alone, so two builds of one tree are byte-equal.
  writeFileSync(metaFile, `${JSON.stringify(meta, null, 2)}\n`);
  console.log(`[scribe-bundle] wrote ${OUT} (inputs ${meta.inputs.length}, ${kb} KB, hash ${meta.sourceHash})`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  await main();
}
